import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronDown, Check } from 'lucide-react';
import clsx from 'clsx';
import './AcidSelect.css';

export interface SelectOption {
    value: string;
    label: string;
    description?: string;
    icon?: React.ReactNode;
}

export interface AcidSelectProps {
    options: SelectOption[];
    value?: string;
    defaultValue?: string;
    onChange?: (value: string) => void;
    placeholder?: string;
    label?: string;
    className?: string;
    disabled?: boolean;
}

export const AcidSelect = ({
    options,
    value,
    defaultValue,
    onChange,
    placeholder = 'SELECT_OPTION...',
    label,
    className,
    disabled = false
}: AcidSelectProps) => {
    const [isOpen, setIsOpen] = useState(false);
    const [internalValue, setInternalValue] = useState(defaultValue || '');
    const containerRef = useRef<HTMLDivElement>(null);

    const currentValue = value !== undefined ? value : internalValue;
    const selectedOption = options.find(opt => opt.value === currentValue);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleSelect = (val: string) => {
        if (disabled) return;
        setInternalValue(val);
        onChange?.(val);
        setIsOpen(false);
    };

    return (
        <div className={clsx('ac-select-container', className, disabled && 'ac-select-disabled')} ref={containerRef}>
            {label && <label className="ac-select-label">{label}</label>}

            <div
                className={clsx('ac-select-trigger', isOpen && 'ac-select-trigger-open')}
                onClick={() => !disabled && setIsOpen(!isOpen)}
            >
                <div className="ac-select-value-area">
                    {selectedOption?.icon && <span className="ac-select-icon">{selectedOption.icon}</span>}
                    <span className={clsx('ac-select-display-value', !selectedOption && 'placeholder')}>
                        {selectedOption ? selectedOption.label : placeholder}
                    </span>
                </div>
                <ChevronDown size={16} className={clsx('ac-select-chevron', isOpen && 'rotate')} />
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 5 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 5 }}
                        transition={{ duration: 0.15 }}
                        className="ac-select-dropdown"
                    >
                        <div className="ac-select-options">
                            {options.map((option) => (
                                <div
                                    key={option.value}
                                    className={clsx('ac-select-option', option.value === currentValue && 'selected')}
                                    onClick={() => handleSelect(option.value)}
                                >
                                    <div className="ac-option-main">
                                        {option.icon && <span className="ac-option-icon">{option.icon}</span>}
                                        <div className="ac-option-text">
                                            <span className="ac-option-label">{option.label}</span>
                                            {option.description && <span className="ac-option-desc">{option.description}</span>}
                                        </div>
                                    </div>
                                    {option.value === currentValue && <Check size={14} className="ac-option-check" />}
                                </div>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

.ac-select-container {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    width: 100%;
    position: relative;
}

.ac-select-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--ac-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.ac-select-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 44px;
    padding: 0 1rem;
    background: var(--ac-surface);
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-sm);
    cursor: pointer;
    transition: all 0.2s ease;
}

.ac-select-trigger:hover {
    border-color: var(--ac-border-bright);
    background: var(--ac-surface-hover);
}

.ac-select-trigger-open {
    border-color: var(--ac-brand);
    background: var(--ac-surface-hover);
    box-shadow: 0 0 0 1px var(--ac-brand);
}

.ac-select-value-area {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    overflow: hidden;
}

.ac-select-display-value {
    font-family: var(--font-mono);
    font-size: 0.85rem;
    color: var(--ac-text-primary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.ac-select-display-value.placeholder {
    color: var(--ac-text-muted);
}

.ac-select-chevron {
    color: var(--ac-text-muted);
    transition: transform 0.3s ease;
}

.ac-select-chevron.rotate {
    transform: rotate(180deg);
    color: var(--ac-brand);
}

.ac-select-dropdown {
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    width: 100%;
    background: var(--ac-surface);
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-sm);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.5);
    z-index: 1000;
    max-height: 300px;
    overflow-y: auto;
    padding: 4px;
}

.ac-select-option {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 12px;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.ac-select-option:hover {
    background: var(--ac-surface-hover);
}

.ac-select-option.selected {
    background: rgba(244, 67, 54, 0.1);
}

.ac-select-option.selected .ac-option-label {
    color: var(--ac-brand);
}

.ac-option-main {
    display: flex;
    align-items: center;
    gap: 12px;
}

.ac-option-text {
    display: flex;
    flex-direction: column;
}

.ac-option-label {
    font-family: var(--font-mono);
    font-size: 0.85rem;
    color: var(--ac-text-primary);
}

.ac-option-desc {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--ac-text-muted);
}

.ac-option-check {
    color: var(--ac-brand);
}

.ac-select-disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

[data-theme='light'] .ac-select-dropdown {
    background: white;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}
